const maxDaily = 1_000_000_000_000;
const maxMonthly = maxDaily * 31;
const nameField = (label: string, maxLength: number, guidance: string) =>
  prop.text({ label, maxLength, required: true, pattern: "\\S", guidance });

const fields = {
