                        </Column>
                        <Column style={{ gap: 2 }}>
                          <Text field={`speakers[${i}].name`} style={{ fontWeight: 700 }}>{speaker.name}</Text>
                          <Text field={`speakers[${i}].role`} style={{ fontSize: token("fontSizes.small"), color: token("colors.muted") }}>{speaker.role}</Text>
