// documents/certificate/template.tsx, from hyperelements.dev/templates. Replace the brand block with your own brand.

import { Column, Document, Heading, Image, Layer, Link, Polygon, Row, Span, Svg, Text, defineTheme, prop, token } from "@hyper-elements/react";
import type { Theme } from "@hyper-elements/react";
import { field, template } from "@hyper-elements/react/template";

/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show: a marketing email shows it. */
  address?: string;
  /**
   * The brand's site, the hosts its links may go to (`acme.example`, or `*.acme.example`), and the pages a template
   * links to that belong to the brand, not to a send: where a reader unsubscribes in one step, chooses which emails
   * they get, and gets help. `payments` are other hosts a payment link may go to (a payment processor's).
   */
  links: {
    site: string;
    domains: readonly string[];
    unsubscribe: string;
    preferences: string;
    help: string;
    payments?: readonly string[];
  };
  /** The currency amounts are in, as an ISO 4217 code ("USD"), written in the brand's language. */
  currency: string;
  /** Who the brand is in law, for invoices and receipts: its registered name, and its tax or VAT number. */
  legal?: { entity: string; taxId?: string };
  /** How a reader reaches support, where a template shows it. */
  support?: { phone?: string; hours?: string };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Orbit",
  theme: defineTheme({
    colors: {
      background: "#ffffff",
      foreground: "#0b1020",
      primary: "#4f46e5",
      primaryForeground: "#ffffff",
      border: "#e2e5ee",
      muted: "#5b6478",
      surface: "#f4f5fa",
      accent: "#2dd4bf",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "Inter, 'Helvetica Neue', Arial, sans-serif" },
    fontSizes: { body: 16, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 16, lg: 24, xl: 40 },
    radii: { sm: 6, md: 12 },
    elements: {
      Heading: {
        fontWeight: 700,
        by: {
          level: {
            1: { fontSize: 32, lineHeight: 1.15 },
            2: { fontSize: 24, lineHeight: 1.25 },
            3: { fontSize: 19, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/gallery/assets/brands/orbit/logo.png", width: 480, height: 120, alt: "Orbit" },
  address: "1 Main Street, Springfield",
  links: {
    site: "https://orbit.example",
    domains: ["orbit.example", "*.orbit.example"],
    unsubscribe: "https://orbit.example/unsubscribe",
    preferences: "https://orbit.example/account/emails",
    help: "https://orbit.example/help",
  },
  currency: "USD",
  legal: { entity: "Orbit Software, Inc.", taxId: "EIN 12-3456789" },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
  ],
};
// brand: end

/** Whether a `#rgb` or `#rrggbb` color is light: dark ink reads on it better than light ink does. */
function isLight(color: string): boolean {
  const hex = color.length === 4 ? color.replace(/[0-9a-f]/gi, (d) => d + d) : color;
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255).map((c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r! + 0.7152 * g! + 0.0722 * b! > 0.18;
}

const fields = {
  recipient: prop.text({ label: "Recipient", required: true, maxLength: 60, guidance: "Their name as they'd like it printed" }),
  photo: field.image({
    label: "Recipient's photo",
    accepts: ["png", "jpeg"],
    // Drawn in a circle 116px across, cropped from its center: a square portrait, or close to one.
    fit: "cover",
    aspect: { min: 0.8, max: 1.25 },
    minWidth: 232,
    minHeight: 232,
    guidance: "A portrait with their face in the center",
  }),
  achievement: prop.text({
    label: "Achievement",
    required: true,
    pattern: "^[\\s\\S]{12,120}$",
    guidance: "What they did, as a sentence without its subject or a full stop: Completed the Foundations of Accessible Design course, with distinction",
  }),
  dateAwarded: prop.text({
    label: "Date awarded",
