    { part: "WR-2-C-H", description: "WR-2 with a 6-way 2.54 mm header fitted", pack: "Bag of 10" },
    { part: "WR-2-C-T", description: "WR-2 on tape and reel, for pick and place", pack: "Reel of 500" },
