const symbol = prop.text({ label: "Symbol", maxLength: 10, pattern: "^[A-Za-zΔ]{1,4}(_[A-Za-z0-9;]{1,7})?$", guidance: "A subscript follows an underscore: V_IN, t_SU;DAT." });

