  ),
  ratings: prop.list(
    prop.object(
      { parameter: prop.text({ label: "Parameter", required: true, maxLength: 44 }), symbol, min: limit("Min"), max: limit("Max"), unit: prop.text({ label: "Unit", required: true, maxLength: 5 }) },
