/** A month and day, with no year, so it reads the same any time. */
const date = (label: string, guidance: string) => prop.text({ label, required: true, pattern: "^(?![\\s\\S]*\\b(19|20)\\d{2}\\b)[\\s\\S]{3,14}$", guidance });

const fields = {
