      foreground: "#ffffff",
      primary: "#ffe14d",
      primaryForeground: "#1a0b3d",
      border: "#3b2a75",
      muted: "#cdc4ff",
      surface: "#28145a",
      accent: "#ff4fa3",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "Inter, 'Helvetica Neue', Arial, sans-serif" },
