                    {v.eyebrow}
                  </Text>
                </Row>
              )}
              <Heading field="headline" level={1} fit={{ sizes: { min: 48, max: 72, step: 4 }, maxLines: 3 }} style={{ lineHeight: 1.06 }}>
                {v.headline}
              </Heading>
