    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 6, sm: 12, md: 20, lg: 32, xl: 56 },
    radii: { sm: 8, md: 20 },
    elements: {
      Heading: {
        fontWeight: 800,
        by: {
          level: {
            1: { fontSize: 40, lineHeight: 1.15 },
            2: { fontSize: 28, lineHeight: 1.25 },
