  const u = width / 1320;
  const top = height * 0.43;
  const spacing = 118 * u;
  const count = Math.ceil((height - top) / spacing) + 1;
  const line = (i: number) =>
    `M${Array.from({ length: 23 }, (_, j) => {
      const x = j * 60;
      const y = 46 * Math.sin(x / 230 + i * 0.7) + 22 * Math.sin(x / 97 + i * 1.9);
